public class Demo2 {
    public static void main(String[] args) {
        try {
            System.out.println("Outer try starts");
            try {
                System.out.println("Inner try starts");
                System.out.println(5 / 0);
                System.out.println("Inner try ends");
            }
            catch (NullPointerException e) {
                System.out.println("Nulls are not allowed");
            }
            System.out.println("Outer try ends");
        }
        catch (ArithmeticException e) {
            System.out.println("Divide by zero not allowed : Outer");
        }
    }
}

public class Catches {
    static void m1() {
        try { System.out.println(5 / 0); }
        catch (ArithmeticException e) { }
        catch (RuntimeException e) { }
    }

    static void m2() {
        try { System.out.println(5 / 0); }
        catch (ArithmeticException | NullPointerException e) { }
        catch (Exception e) { }
    }

    static void m3() {
        try { System.out.println(5 / 0); }
        catch (RuntimeException e) { }
        catch (ArithmeticException e) { }
    }

    static void m4() {
        try { System.out.println(5 / 0); }
        catch (Exception e) { }
    }
}

public class Demo4 {
    public static void main(String[] args) {
        try {
            checkEligibility(20);
            checkEligibility(-5);
            checkEligibility(30);
        }
        catch (InvalidAgeException e) {
            System.out.println(e.getMessage());
            System.out.println("Entered age was " + e.getAge());
        }
    }

    private static void checkEligibility(int age) throws InvalidAgeException {
        if (age <= 0) {
            throw new InvalidAgeException("Age cannot be negative", age);
        }
        if (age > 18) {
            System.out.println("You are eligible to vote");
        }
    }
}

class InvalidAgeException extends Exception {
    private int age;

    public InvalidAgeException(String message, int age) {
        super(message);
        this.age = age;
    }

    public int getAge() {
        return this.age;
    }
}
